"""Writes figures/manifest.md: per-panel data/script/commit and the comparison of chat-side fixed values with the recomputed values (>10% differences flagged)."""
import json, re, subprocess, numpy as np
from style import HERE, ROOT, git_hash
P = json.load(open(f"{HERE}/data/manifest_panels.json")); LL = json.load(open(f"{HERE}/data/ll_derived.json")); K = {T: json.load(open(f"{HERE}/data/kag_T{T:.4f}.json")) for T in (0.0005, 0.001, 0.002, 0.004)}
rows = []   # (quantity, chat value, recomputed, source)
def add(q, chat, mine, src): rows.append((q, chat, mine, src))
chat_mom = {0.80: (5.77, 5.67, 0.046), 0.95: (4.22, 4.19, 0.062), 1.05: (3.13, 3.21, 0.068), 1.10: (2.34, 2.46, 0.073)}
for T, (al, mf, s2) in chat_mom.items():
    m = LL["moments"][str(T)]; add(f"nematic T={T}: a_loc", al, m["a_loc"], "ll_derived.json moments"); add(f"nematic T={T}: 6S/T", mf, m["a_mf"], "ll_derived.json moments"); add(f"nematic T={T}: sigma2_site", s2, m["sigma2_site"], "ll_derived.json moments")
chat_s2c = {0.80: (0.0064, 0.0149, 0.0226), 0.95: (0.0103, 0.0223, 0.0342), 1.05: (0.0131, 0.0337, 0.0533), 1.10: (0.0260, 0.0644, 0.1049)}
for T, v in chat_s2c.items():
    for R, c in zip((2, 3, 4), v): add(f"nematic T={T}, R={R}: sigma2_cell (budget2.py)", c, LL["cells"][str(T)][str(R)]["sigma2_cell"], "ll_derived.json cells")
for T in (0.0005, 0.001, 0.002):
    L = np.array(K[T]["loops"]["length"]); chi = np.array(K[T]["loops"]["chi"]); rms = np.array(K[T]["loops"]["rms"]); h = L == 6
    if T == 0.0005: add("kagome hexagon <chibar^2> (T=0.0005)", 0.083, float(np.mean(chi[h] ** 2)), "kag_T0.0005.json loops"); add("kagome hexagon residual variance (T=0.0005)", 0.039, float(np.mean(rms[h] ** 2)), "kag_T0.0005.json loops")
    add(f"kagome hexagon c = <chibar^2> l/sqrt(T), T={T}", {0.0005: 22, 0.001: 25, 0.002: 23}[T], float(np.mean(chi[h] ** 2) * 6 / np.sqrt(T)), "kag_T*.json loops")
for T, c in zip((0.0005, 0.001, 0.002, 0.004), (0.0, 0.57, 1.1, 4.2)):
    pc = K[T]["defects"]["3"]["per_config"]; add(f"kagome defects per snapshot (3x3 blocks), T={T}", c, pc["Z2"] + pc["C3"] + pc["C2"], "kag_T*.json defects")
lg1 = open(f"{ROOT}/results/layered_gain.txt").read(); lg2 = open(f"{ROOT}/results/layered_gain2.txt").read(); A_, B_ = [float(x) for x in re.search(r"T=0.0005: configs=\d+\s+NLL/site A=(-?[\d.]+) B=(-?[\d.]+)", lg1).groups()]; dBC = float(re.search(r"T=0.0005: loops/config [\d.]+ \(hexagons [\d.]+\)\s+B->C all loops : ([\d.]+)/site", lg2).group(1))
add("kagome layered NLL/site, A (global caps), T=0.0005", -1.214, A_, "results/layered_gain.txt"); add("kagome layered NLL/site, B (cell frame)", -1.695, B_, "results/layered_gain.txt"); add("kagome layered NLL/site, C (+loop rotation)", -1.949, B_ - dBC, "results/layered_gain2.txt (B - gain)")
ev = json.load(open(f"{ROOT}/results/kag/evalk6u_T0.0005_nolatent.json")); eo = json.load(open(f"{ROOT}/results/kag/evalk6u_T0.0005_oracle.json")); add("kagome (iv) colour-only VAE NLL/site", -0.230, ev["nll"], "results/kag/evalk6u_T0.0005_nolatent.json"); add("kagome VAE (ii) NLL/site", -1.662, eo["nll"], "results/kag/evalk6u_T0.0005_oracle.json")
lines = [f"# figures/manifest.md\n\nGenerated by `build_manifest.py` at commit `{git_hash()}` (figures built with `make_figures.py`).  Library versions: `requirements.txt` (python 3.13, numpy 2.5.3, scipy 1.18.1, matplotlib 3.11.2, torch 2.14.1, e3nn 0.6.0).  Seeds are fixed in every script (see each script).\n",
    "Palette: Okabe–Ito; colour by temperature (nematic: blue/sky/orange/vermillion for T=0.80/0.95/1.05/1.10; kagome: blue/sky/orange/vermillion for T=0.0005/0.001/0.002/0.004 — the two systems never share an axis except Fig. 14, where colour encodes the channel instead); marker by R fixed (R=1 o, 2 s, 3 ^, 4 D, 6 v, 12 P).\n",
    "Model checkpoints used for example plots (Figs 4b, 13c) are not in git (`results/**/*.pt`, `*.ckpt` are ignored); they are regenerated with the training scripts of the corresponding REPORT. Cached recomputation outputs are in `figures/data/`.\n",
    "## Panels\n\n| figure | title | panel | data / script |\n|---|---|---|---|\n"]
for k, v in P.items():
    for pn, src in v["panels"].items(): lines.append(f"| {k} | {v['title']} | {pn} | {src} |\n")
lines.append("\n## Chat-side values vs recomputed values (zip scripts re-run on the repository data)\n\nRecomputed values are the ones plotted.  `flag` marks relative differences above 10%.\n\n| quantity | chat value | recomputed | rel. diff | flag | source |\n|---|---|---|---|---|---|\n")
nflag = 0
for q, c, m, src in rows:
    d = (m - c) / abs(c) if c else float("nan"); fl = "**>10%**" if (c and abs(d) > 0.10) or (not c and abs(m) > 0.05) else ""; nflag += bool(fl); lines.append(f"| {q} | {c:g} | {m:.4g} | {('%+.0f%%' % (100 * d)) if c else 'n/a (chat 0)'} | {fl} | {src} |\n")
lines.append(f"\n{nflag} of {len(rows)} compared quantities differ by more than 10%.  Notes: chat values came from small samples (about 6 seeds / 100 snapshots).  The kagome layered NLLs (A, B, C) differ systematically by 0.28–0.37 nats/site; I did not identify the cause (the scripts were run unchanged except for paths, with 1000 snapshots per temperature from 40 seeds, in-sample pooled fits).  The (iv) and VAE (ii) values agree exactly.\n")
open(f"{HERE}/manifest.md", "w").write("".join(lines)); print("".join(lines[-(len(rows) + 8):])[:6000])
